style.css:
/*
 * Estilo para https://gmmmc.phidias.co/ (Phidias)
 * Fondo: Aguamarina (#7FFFD4)
 * Texto: Gris azulado (#688391)
 * Fuente: Vivaldi
 */
@-moz-document domain("gmmmc.phidias.co") {
/* 1. Fondo de la página principal (body) y fuente global */
    body, html {
        background-color: #7FFFD4 !important; /* Aguamarina */
        color: #688391 !important;           /* Gris azulado para el texto */
        font-family: "Vivaldi", cursive, sans-serif !important;
    }
    
    /* 2. Forzar el color y la fuente en todo el texto, títulos y enlaces */
    * {
        color: #688391 !important;
        font-family: "Vivaldi", cursive, sans-serif !important;
    }

    /* 3. Fondo del contenedor principal de login (la caja blanca) */
    /* Apunta al contenedor principal de la tarjeta de login y el pie de página */
    .card, .page-footer {
        background-color: #C1E8DD !important; /* Un tono más claro para el formulario */
        border: 1px solid #688391 !important;
        box-shadow: none !important;
    }
    
    /* 4. Campos de entrada de texto (inputs) */
    .form-control, input[type="text"], input[type="password"] {
        background-color: #E0FFFF !important; /* Un blanco azulado para el campo */
        color: #688391 !important;
        border: 1px solid #688391 !important;
    }

    /* 5. Botones (Ingresar) */
    .btn-primary, .btn-primary:focus, .btn-primary:active {
        background-color: #4682B4 !important; /* Azul más oscuro para destacar */
        border-color: #4682B4 !important;
        color: white !important;
        font-weight: bold !important;
    }
    
    .btn-primary:hover {
        background-color: #36648B !important;
        border-color: #36648B !important;
    }
    
    /* 6. Enlace de "Restablecer o crear contraseña" */
    a, .link {
        color: #4682B4 !important; /* Color de enlace diferente */
    }
}
